@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Title;
    var posts = Model.Children<BlogPost>()?.OrderByDescending(p => p.PublishDate).ToList() ?? new List<BlogPost>();
}

<section class="mb-10">
    <h1 class="text-4xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
    @if (!string.IsNullOrWhiteSpace(Model.Intro))
    {
        <p class="mt-3 text-lg text-slate-600">@Model.Intro</p>
    }
</section>

<section class="mb-12">
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</section>

<section>
    <h2 class="mb-6 text-2xl font-semibold text-slate-900">Latest posts</h2>
    <ul class="grid gap-6 sm:grid-cols-2">
        @foreach (var post in posts)
        {
            var imageUrl = post.ListingImage?.GetCropUrl(width: 800, height: 450);
            <li class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                <a href="@post.Url()" class="block">
                    @if (!string.IsNullOrEmpty(imageUrl))
                    {
                        <img src="@imageUrl" alt="@post.ListingImage?.Name" class="aspect-video w-full object-cover" loading="lazy" />
                    }
                    <div class="p-5">
                        <p class="text-xs uppercase tracking-wide text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</p>
                        <h3 class="mt-1 text-xl font-semibold text-indigo-700">@post.Title</h3>
                        <p class="mt-2 text-slate-600">@post.Excerpt</p>
                    </div>
                </a>
            </li>
        }
    </ul>
</section>

