@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Title;
    var heroUrl = Model.ListingImage?.GetCropUrl(width: 1200, height: 500);
}

<article>
    <a href="@Model.Parent?.Url()" class="text-sm text-indigo-700 hover:underline">&larr; All posts</a>
    <header class="mt-4 mb-8">
        <p class="text-xs uppercase tracking-wide text-slate-500">@Model.PublishDate.ToString("d MMMM yyyy")</p>
        <h1 class="mt-1 text-4xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
        @if (!string.IsNullOrWhiteSpace(Model.Excerpt))
        {
            <p class="mt-3 text-lg text-slate-600">@Model.Excerpt</p>
        }
    </header>
    @if (!string.IsNullOrEmpty(heroUrl))
    {
        <img src="@heroUrl" alt="@Model.ListingImage?.Name" class="mb-8 aspect-[12/5] w-full rounded-xl object-cover" />
    }
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</article>

