cd /tmp && for p in why-mcp-is-awesome mcp-makes-tools-talk; do curl -k -s -o $p.html -w "$p %{http_code}
" https://localhost:44317/$p/; echo " could-not-render: $(grep -c 'Could not render component' $p.html)  richtext-paras: $(grep -c 'text-lg leading-8' $p.html)  figure: $(grep -c '<figure' $p.html)  quote: $(grep -c '<blockquote' $p.html)  img-srcs: $(grep -o '<img src="[^"]*"' $p.html | wc -l)"; done; echo "home: richtext=$(grep -c 'text-lg leading-8' home.html) cards=$(grep -c 'rounded-xl border' home.html)"; grep -o '<img src="[^"]*"' why-mcp-is-awesome.html; U=$(grep -o '<img src="[^"]*"' why-mcp-is-awesome.html | head -1 | sed 's/<img src="//;s/"$//;s/&amp;/\&/g'); curl -k -s -o /dev/null -w "image %{http_code}
" "https://localhost:44317$U"; curl -k -s -o /dev/null -w "css %{http_code}
" https://localhost:44317/dist/site.css

